#!/usr/bin/env python3
"""Genera el atlas local reproducible. Fuentes: boletines y portales públicos citados.
No almacena copias de normas de terceros ni afirma una verificación que no consta.
"""
import json,csv,re,unicodedata,pathlib,datetime
root=pathlib.Path(__file__).parent
rows=[]; sources=[]; stars=[]
levels={
 'especifica':'Ley o reglamento específico',
 'sectorial':'Regulación sectorial obligatoria',
 'subnacional':'Normativa subnacional identificada',
 'general':'Marco general o urbanístico',
 'guia':'Directriz o estándar no general',
 'pendiente':'Pendiente de documentar'
}
def C(iso,name,region,level,summary,scope='Nacional',confidence='Fuente primaria identificada',note='',keywords=''):
    rows.append(dict(iso=iso,name=name,region=region,level=level,summary=summary,scope=scope,confidence=confidence,note=note,keywords=keywords,source_ids=[],star_ids=[]))
def S(iso,title,url,typ='Norma',effect='Ámbito y vigencia según la fuente',note='',year=''):
    n=len(sources)+1; sid=f'F{n:03d}'
    sources.append(dict(id=sid,country=iso,title=title,url=url,type=typ,effect=effect,note=note,year=year,official=bool(url and not any(d in url for d in ['lexivox.org','strapi.lexis.com.ec','indiacode.ecourtsindia.com']))))
    next(r for r in rows if r['iso']==iso)['source_ids'].append(sid)
    return sid
def M(iso,title,description,force,param,scope,sources_,caution='',replicability='Alta'):
    mid=f'M{len(stars)+1:02d}'
    stars.append(dict(id=mid,country=iso,title=title,description=description,force=force,param=param,scope=scope,sources=sources_ if isinstance(sources_,list) else [sources_],caution=caution,replicability=replicability))
    next(r for r in rows if r['iso']==iso)['star_ids'].append(mid)

