jsondir=root/'data'; jsondir.mkdir(exist_ok=True)
all_data=dict(meta=dict(title='Atlas de legislación sobre contaminación lumínica',date='2026-11-19',country_count=len(rows),source_count=len(sources),star_count=len(stars),scope='Estudio comparado y bibliografía de trabajo; no asesoramiento jurídico',disclaimer='La inclusión de un país no implica existencia de ley específica. Las fuentes y vigencia deben cotejarse antes del uso jurídico. Los informes originales de las primeras fases no se han recuperado íntegramente.'),levels=levels,countries=rows,sources=sources,stars=stars)
(jsondir/'atlas.json').write_text(json.dumps(all_data,ensure_ascii=False,indent=2),encoding='utf8')
def export_csv(filename,cols,records):
    with (jsondir/filename).open('w',newline='',encoding='utf-8-sig') as f:
        w=csv.DictWriter(f,fieldnames=cols,extrasaction='ignore');w.writeheader()
        for r in records:
            v={k:('; '.join(x) if isinstance(x,list) else x) for k,x in r.items()};w.writerow(v)
export_csv('paises.csv',list(rows[0]),rows)
export_csv('fuentes.csv',list(sources[0]),sources)
export_csv('medidas_estrella.csv',list(stars[0]),stars)

def slug(s):
    n=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode('ascii').lower()
    return re.sub('[^a-z0-9]+','-',n).strip('-')
source_index={s['id']:s for s in sources}
for r in rows:
    lines=[f"# {r['name']} — ficha legal de contaminación lumínica",'',f"**Jurisdicción:** {r['scope']}  ",f"**Clasificación:** {levels[r['level']]}  ",f"**Evidencia:** {r['confidence']}  ",f"**Corte:** 19 de noviembre de 2026",'', '## Síntesis',r['summary'],'']
    if r['note']:lines+=['## Cautelas',r['note'],'']
    if r['star_ids']:
        lines+=['## Medidas estrella','']
        for m in stars:
            if m['id'] in r['star_ids']:
                lines += [f"### {m['title']}",m['description'],'',f"- Fuerza jurídica: {m['force']}",f"- Parámetro: {m['param']}",f"- Alcance: {m['scope']}",f"- Cautela: {m['caution']}",'']
    lines+=['## Referencias documentales','']
    for sid in r['source_ids']:
        s=source_index[sid]
        lines +=[f"- **{sid}** — [{s['title']}]({s['url']}). Tipo: {s['type']}. Ámbito: {s['effect']}. {s['note']}"]
    lines+=['','---','La ficha no sustituye el texto oficial consolidado. No extrapolar normas de territorios subnacionales a todo el país.']
    (root/'docs'/f"{r['iso']}_{slug(r['name'])}.md").write_text('\n'.join(lines)+'\n',encoding='utf8')

lines=['# Atlas mundial de legislación sobre contaminación lumínica','', '**Informe maestro de compilación documental — 19 de noviembre de 2026**','',f"- **{len(rows)} países** en el universo; no equivale a 51 leyes nacionales.",f"- **{len(sources)} registros bibliográficos** con enlaces a documentos y portales; algunos son guías, borradores o fuentes secundarias.",f"- **{len(stars)} medidas estrella** con fuerza jurídica diferenciada.",'', '## Alcance y procedencia','', 'Este dossier es una **reconstrucción consolidada** de fuentes primarias, referencias y fichas de 51 jurisdicciones. Se ha tenido acceso al informe de la última ampliación (14 países) y a material complementario sobre legislación española. Los textos completos originales de las primeras fases de 22 y 37 países **no estaban disponibles íntegramente**, por lo que no se afirma haberlos fusionado literalmente. Las fichas de esas fases han sido reconstruidas y deben seguir revisándose con fuentes oficiales actualizadas.','', 'El estado de revisión es heterogéneo. La clasificación refleja la **naturaleza de los instrumentos identificados**, no el grado de eficacia ambiental ni la ausencia definitiva de normas.', '', '## Clasificación utilizada','']
for k,v in levels.items():lines +=[f'- **{v}:** categoría de visualización «{k}», sin representar ranking de rigor.']
lines += ['','## Matriz comparativa de 51 países','','| País | Región | Tipo de instrumento localizado | Ámbito | Referencias |','|---|---|---|---|---:|']
for r in sorted(rows,key=lambda r:(r['region'],r['name'])):
    lines += [f"| {r['name']} | {r['region']} | {levels[r['level']]} | {r['scope']} | {len(r['source_ids'])} |"]
lines += ['','## Medidas estrella','','La columna fuerza jurídica separa límites exigibles, políticas de planeamiento, habilitaciones, recomendaciones y proyectos.','', '| País | Medida | Parámetro | Fuerza jurídica | Fuente(s) |','|---|---|---|---|---|']
for m in stars:
    r=next(x for x in rows if x['iso']==m['country'])
    links=', '.join(f"[{sid}]({source_index[sid]['url']})" for sid in m['sources'])
    lines+=[f"| {r['name']} | {m['title']} | {m['param'].replace('|','/')} | {m['force']} | {links} |"]
lines+=['','## Bibliografía y referencias','']
for s in sources:
    r=next(x for x in rows if x['iso']==s['country'])
    lines += [f"- **{s['id']} — {r['name']}** — [{s['title']}]({s['url']}); {s['type']}, {s['effect']}. {s['note']}"]
lines+=['','## Advertencias de interpretación','', '- No presentar una norma voluntaria, un borrador o un mandato para legislar como un límite fotométrico de obligado cumplimiento.', '- No aplicar una ordenanza de un municipio o estado a todo el país.', '- No tratar la falta de una ley localizada como prueba de ausencia absoluta de normas.', '- Polonia: límite lux en régimen transitorio 2026, distinguir del texto formalmente derogado.', '- España: art. 2.2.b Ley 34/2007 limita aplicación automática del régimen general de emisiones.', '- Alemania: entrada en vigor del §41a BNatSchG por verificar.', '- Colombia: la versión relevante es la Resolución 40286/2026, con transición.', '- Chile: considerar aplicación nacional 2026 y zonas de protección con cronología diferenciada.', '- Malasia: el documento MS 825-4 consultado es BORRADOR.', '- Omán: decreto de creación de reserva no equivale a adoptar todas las propuestas de control lumínico.', '- Ecuador: el documento localizado requiere cotejo con fuente oficial.', '- En 51 países, el examen de todas las ordenanzas municipales y sus reformas es un trabajo jurídico abierto.', '', '## Cómo seguir mejorando esta edición','', 'Actualizar cada ficha comparando textos consolidados oficiales, registrar fecha de consulta, archivar solo documentos cuando su licencia/condiciones lo permitan, y añadir tablas estructuradas de artículos y umbrales. Mantener bitácora de cambios y revisión por expertos jurídicos locales.']
(root/'INFORME_MAESTRO.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
print('PAISES',len(rows),'FUENTES',len(sources),'MEDIDAS',len(stars),'FICHAS',len(list((root/'docs').glob('*.md'))))

